// The help text behind the 3-stage pipeline controls. Moved here verbatim from FaceSwap.jsx / Settings.jsx when the
// controls became one shared component (PipelineControls.jsx), so the two tabs cannot drift apart again.

export const SWAPPER_INFO = "realswap (default) pairs hyperswap and hififace and sends each face to ONE of them — it never blends the two, so nothing can double. Measured over a yaw sweep: below profile it is byte-identical to hyperswap, and at ±90° it cuts the frames where the swap lands the face somewhere the original was not from 80 to 35. Only one net runs per face, so it costs the same as hyperswap plus a pose solve. CAVEAT, worth knowing before you trust it: the pose test that decides the route was calibrated on studio stills and over-fires on real video — on a normal two-person clip 69% of faces took the hififace route, which carries noticeably less of the faceset's identity. If a render looks less like your source than hyperswap did, that is why; switch to hyperswap and compare. · inswapper 128 · reswapper/hyperswap(a/b/c)/ghost(1-3)/simswap/blendswap/uniface/hififace 256 · simswap_512 (each downloads on first use; ghost/simswap/hififace use their own alignment + identity converter). COST PER FACE, measured on an RTX 4070 TensorRT FP16 at the 256px subsample — note this is per FACE, not per inference, because a model smaller than the subsample size is tiled and run (subsample/size)² times: ghost_1 3.7ms, hyperswap a/c 5.3ms, hyperswap_1b 5.6ms, hififace 6.1ms, simswap 6.7ms, ghost_3 11.4ms, simswap_512 11.6ms, blendswap 13.2ms, reswapper 16.4ms, and inswapper 21.1ms — inswapper is 5.3ms per call but 128px, so at 256px subsample it runs FOUR times per face and is the most expensive option here despite looking near-cheapest. The whole spread is ~17ms against a swap stage reporting ~46ms per face, so unless you are on inswapper this is a quality choice, not a speed one.";

export const BYPASS_INFO = "ROOP_AUTO_BYPASS_RESTORER_NATIVE_SWAP -- When using Alpha 256 or HyperSwap and face bbox height is <= 320px, skip full neural restorers (CodeFormer, GFPGAN, RF++) and apply a fast GPU Difference-of-Gaussians (DoG) unsharp mask instead, boosting Stage 3 throughput by up to 3x.";

export const SMART_SKIP_INFO = "ROOP_TEMPORAL_SMART_SKIP -- During Stage 2 Pre-Pass, detects near-static faces (displacement < 0.15px and stable illumination) across consecutive frames and bypasses Swapper + Restorer neural inference in Stage 3 by warping the previous frame's composited face patch forward using dense NVOFA optical flow, up to 2 consecutive frames.";

export const STRIDE_INFO = "ROOP_PREPASS_DETECT_INTERVAL -- run the face detector on every Nth frame of the tracking pre-pass and carry the faces in between by optical flow, bridging each hole between two real detections. Unlike \"Face tracking interval\" it still reads every frame's pixels. Measured on three 900-frame clips against detecting every frame: N=2 saves 11-14% of the pre-pass, N=4 saves 21-26%, N=8 about 30% - and in exchange finds fewer faces (N=4: 3-10% fewer; N=8: 9-20% fewer) and binds fewer of them to your source (N=4: up to 25% fewer frames matched; N=8: up to 31% fewer), because a track seen only every Nth frame has fewer chances to match. The frames the flow follows land within about 1% of an eye distance (median); the ones it could not follow are placed by plain interpolation and sit 13-40% off. Leave it at 1 unless the footage is steady and the person is near-frontal.";
